/**
 * 布局组件
 * @author 恒哥
 */
import React from 'react';
import { Link } from 'gatsby';
import { useLocation } from '@reach/router';
import Navigation from '../Navigation';
import AnalyticsConsent from '../AnalyticsConsent';
import { I18nProvider, useI18n } from '../../i18n';
import {
  COMPANY_DESCRIPTION,
  MESSAGING_PRODUCT_NAME,
  PRODUCT_NAME,
  SITE_URL,
  SHOPIFY_APP_STORE_URL,
  SHOPIFY_APP_STORE_LABEL,
  SHOPIFY_INSTALL_PAGE_PATH,
  SUPPORT_EMAIL,
  ECOSYSTEM_GROUPS,
} from '../../constants/brand';
import '../../styles/global.css';
import './layout.css';

/**
 * 壳层：注入语言上下文。
 * 🔴 locale 优先取 Gatsby 传入的 pageContext.locale —— **不能用 useLocation 推路径**，
 *    因为 SSR 阶段它恒返回 `/`，会让 `/de/` 的预渲染 HTML 变成英文（SEO 失效）。
 *    详见 src/i18n/index.js 的说明。
 */
export default function Layout({ children, locale }) {
  const { pathname } = useLocation();
  return (
    <I18nProvider pathname={pathname} locale={locale}>
      <Shell>{children}</Shell>
    </I18nProvider>
  );
}

/** 消费语言上下文的页面骨架（导航 + 页脚随语言变化） */
function Shell({ children }) {
  const { t, localePath } = useI18n();
  return (
    <div className="layout">
      <Navigation />
      <main className="main-content">{children}</main>
      <footer className="footer">
        {/* 公司简介（组织级，非某产品描述）。
            🔴 文案真源 = `constants/brand.js` 的 `COMPANY_DESCRIPTION`，与
            `gatsby-config.js` 的 `siteMetadata.description` 同值（改文案两处都要改）。
            刻意写成**英文常量**、不进 i18n 词典 —— 与下方 Contact / Privacy / Terms
            同一处理（法务与联系入口不随语言切换，且不必 en/de/fr 各译一遍）。 */}
        <p className="footer-about">{COMPANY_DESCRIPTION}</p>
        <nav className="footer-ecosystem" aria-label="Whaleal ecosystem sites">
          <p className="footer-ecosystem-title">{t.footer.ecosystemTitle}</p>
          <div className="footer-groups">
            {ECOSYSTEM_GROUPS.map((group) => (
              <div className="footer-group" key={group.id}>
                {/* 🔴 键名 = group.id，与 common.js 的 footer 字典一一对应
                    （见该文件 footer 段的说明）；缺键回落 group.title，不静默消失 */}
                <p className="footer-group-title">
                  {t.footer[group.id] || group.title}
                </p>
                <ul>
                  {group.items.map((item) => (
                    <li key={item.name}>
                      {/* 🔴 两种形态分开渲染（见 constants/brand.js 的 ECOSYSTEM_GROUPS 说明）：
                          `to` = 站内路径 → Gatsby <Link>，会过 localePath（未本地化的页不
                          加语言前缀，加了就是 404）；`url` = 站外绝对地址 → <a target=_blank>。
                          用 `<a href>` 渲染站内路径会丢掉客户端路由并强制新窗口，用户体验上是断的。 */}
                      {item.to ? (
                        <Link to={localePath(item.to)}>
                          {item.name}
                          {item.badge ? (
                            <span className="footer-badge">{item.badge}</span>
                          ) : null}
                        </Link>
                      ) : (
                        <a href={item.url} target="_blank" rel="noopener noreferrer">
                          {item.name}
                          {item.badge ? (
                            <span className="footer-badge">{item.badge}</span>
                          ) : null}
                        </a>
                      )}
                      <span className="footer-site-desc">{item.desc}</span>
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        </nav>
        <p className="footer-links">
          <Link to={localePath('/customers/')}>{t.nav.customers}</Link>
          {' · '}
          <Link to={localePath('/help/')}>{t.nav.help}</Link>
          {' · '}
          <Link to={localePath('/integrations/')}>{t.nav.integrations}</Link>
          {' · '}
          <Link to={localePath('/guides/')}>{t.nav.guides}</Link>
          {' · '}
          <Link to={localePath('/faq/')}>{t.nav.faq}</Link>
          {' · '}
          <Link to={localePath('/about/')}>{t.nav.about}</Link>
          {/* 以下三项刻意用英文常量：与既有的 Privacy / Terms 同一处理（法务与联系入口
              不随语言切换，且这三页本身只在英文路径下存在）。 */}
          {' · '}
          <Link to={localePath('/contact/')}>Contact</Link>
          {' · '}
          <Link to={localePath('/security/')}>Security</Link>
          {' · '}
          <Link to={localePath('/privacy/')}>Privacy</Link>
          {' · '}
          <Link to={localePath('/terms/')}>Terms</Link>
          {' · '}
          <a href={`mailto:${SUPPORT_EMAIL}`}>{SUPPORT_EMAIL}</a>
        </p>
        <p>
          &copy; {new Date().getFullYear()} <a href={SITE_URL}>Whaleal</a>
          {' '}·{' '}
          <Link to={localePath('/messaging/')}>{MESSAGING_PRODUCT_NAME}</Link>
          {' '}· {PRODUCT_NAME}{' '}
          <a href={SHOPIFY_APP_STORE_URL} target="_blank" rel="noopener noreferrer">
            {SHOPIFY_APP_STORE_LABEL}
          </a>
          {' '}·{' '}
          <Link to={localePath(SHOPIFY_INSTALL_PAGE_PATH)}>{t.nav.installFree}</Link>
        </p>
      </footer>
      {/* 分析同意条挂在 Layout 根：全站唯一入口，避免每页各写一份 */}
      <AnalyticsConsent />
    </div>
  );
}
