/**
 * 导航 —— 品牌站口径（2026-10-12 由「Cart 单产品」6 项改为「品牌 + 两条产品线」）
 *
 * Home · Messaging · Cart · Integrations · Pricing · About  + Install free
 *
 * 🔴 **`match` 必须能同时命中带与不带语言前缀的路径**：pathname 在 `/de/` 下是
 *    `/de/pricing/`，用 `p === '/pricing/'` 会漏（当前页高亮丢失，表现为「导航上没有
 *    任何一项是选中态」）。所以一律用 `endsWith` / `includes` 而不是等值比较。
 *
 * 🔴 **新增的 4 个页面族只有英文版**（刻意不进 LOCALIZED_PAGES）：de/fr 页面上点
 *    「Messaging」会到 `/messaging/`（英文），这是正确行为 —— 若 localePath 给它加了
 *    `/de` 前缀，那个路由根本不存在，点导航即 404。
 *
 * ℹ️ Cart 项指向 `/products/`（Cart 功能页）。**不复用 `/pricing/`** —— 那样会让
 *    「Cart」与「Pricing」两个导航项指向同一 URL，用户无从判断区别。
 *
 * @author 恒哥
 */
import React from 'react';
import { Link } from 'gatsby';
import { useLocation } from '@reach/router';
import { SHOPIFY_INSTALL_PAGE_PATH } from '../../constants/brand';
import { useI18n } from '../../i18n';
import NavAuth from '../NavAuth';
import './navigation.css';

/** labelKey 对应 i18n 字典的 nav.*；match 判定当前页（对两种语言的路径都要生效） */
const NAV_ITEMS = [
  {
    to: '/',
    labelKey: 'home',
    // 首页要同时命中 `/`、`/de/`、`/fr/`（含尾斜杠与不带斜杠两种写法）
    match: (p) => /^\/(de|fr)?\/?$/.test(p),
  },
  {
    to: '/messaging/',
    labelKey: 'messaging',
    match: (p) => p.includes('/messaging/'),
  },
  {
    to: '/products/',
    labelKey: 'cart',
    match: (p) => p.endsWith('/products/'),
  },
  {
    to: '/integrations/',
    labelKey: 'integrations',
    match: (p) => p.includes('/integrations/'),
  },
  {
    to: '/pricing/',
    labelKey: 'pricing',
    match: (p) => p.endsWith('/pricing/'),
  },
  {
    to: '/about/',
    labelKey: 'about',
    match: (p) => p.endsWith('/about/'),
  },
];

export default function Navigation() {
  const { pathname } = useLocation();
  const { t, localePath } = useI18n();

  return (
    <nav className="navigation">
      <div className="nav-container">
        <Link to={localePath('/')} className="nav-logo">
          <img
            src="/images/whaleal-icon-112.png"
            width="56"
            height="56"
            alt="Whaleal"
            className="logo-image"
          />
          <span className="nav-brand">
            <span className="nav-brand-name">Whaleal</span>
            <span className="nav-brand-tagline">whaleal.com</span>
          </span>
        </Link>
        <div className="nav-links">
          {NAV_ITEMS.map((item) => (
            <Link
              key={item.to}
              to={localePath(item.to)}
              className={`nav-link ${item.match(pathname) ? 'nav-link-active' : ''}`}
            >
              {t.nav[item.labelKey]}
            </Link>
          ))}
        </div>
        <div className="nav-actions">
          <Link to={localePath(SHOPIFY_INSTALL_PAGE_PATH)} className="nav-button nav-button-primary">
            {t.nav.installFree}
          </Link>
          <NavAuth />
        </div>
      </div>
    </nav>
  );
}
